fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Ensure both vectors have the same length (though problem states this is assumed)
    assert_eq!(a.len(), b.len(), "Input arrays must have the same length");
    
    // Create result vector with the same capacity
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both vectors simultaneously
    for (char_a, char_b) in a.iter().zip(b.iter()) {
        // Validate input characters
        assert!(*char_a == '0' || *char_a == '1', "Input a contains invalid character");
        assert!(*char_b == '0' || *char_b == '1', "Input b contains invalid character");
        
        // Compute XOR: '0' if equal, '1' if different
        let xor_char = if char_a == char_b { '0' } else { '1' };
        result.push(xor_char);
    }
    
    result
}